"""Exercise rclone's local transfer behavior on generated files."""
from hashlib import sha256
from pathlib import Path
from tempfile import TemporaryDirectory
import os
import subprocess

from .config import relative
from .organize_exercise import checksum, verified_copy
from .organize_reconcile import reconcile


def list_file(path, names):
    paths = sorted(names)
    if len(paths) != len(set(paths)) or any(relative(name)!=name or '\n' in name or '\r' in name for name in paths):
        raise ValueError('Rclone list requires distinct normalized paths with one path per line')
    path.write_text(''.join(name+'\n' for name in paths),encoding='utf-8')


def snapshot(root, label):
    return {'scope':label,'version':'isolated-rclone-v1','complete':True,
            'files':[{'path':path.relative_to(root).as_posix(),'size':path.stat().st_size,
                      'sha256':checksum(path)} for path in sorted(root.rglob('*')) if path.is_file()]}


def exercise(rclone):
    version = subprocess.check_output([str(rclone),'version'],text=True,timeout=20).splitlines()[0]
    with TemporaryDirectory(prefix='nas-photo-rclone-') as tmp:
        root = Path(tmp).resolve()
        source, destination, archive, recovery = (root/name for name in ('source','destination','archive','recovery'))
        for path in (source,destination,archive,recovery):
            path.mkdir()
        fixtures = {'Album/01 raw.dng':b'generated raw bytes','Album/01 raw.xmp':b'generated sidecar',
                    '短片.mov':b'generated video data'}
        for name,data in fixtures.items():
            path = source/name
            path.parent.mkdir(exist_ok=True)
            path.write_bytes(data)
        (source/'not-selected.jpg').write_bytes(b'outside declared files list')
        selected = root/'files.txt'
        list_file(selected,fixtures)
        (destination/'outside-list.txt').write_bytes(b'preserve extra target data')
        events = []

        def run(action, flags, event, expected_success=True):
            command = [str(rclone),'--config','/dev/null',action,str(source),str(destination),
                       '--files-from-raw',str(selected),'--checkers','1',*flags]
            result = subprocess.run(command,text=True,capture_output=True,timeout=40)
            if (result.returncode==0) != expected_success:
                raise RuntimeError(f'Rclone {event} exit {result.returncode}: {result.stderr[-900:]}')
            events.append({'action':event,'exit':result.returncode})

        common = ['--immutable','--checksum','--retries','1','--low-level-retries','1','--transfers','1']
        before = snapshot(destination,'destination')
        run('copy',[*common,'--dry-run'],'preview')
        if before!=snapshot(destination,'destination'):
            raise AssertionError('Dry run changed the destination')
        list_file(selected,('Album/01 raw.dng',))
        run('copy',common,'first_batch')
        raw = destination/'Album/01 raw.dng'
        first_stat = raw.stat()
        conflict = destination/'短片.mov'
        bad = b'x'*len(fixtures['短片.mov'])
        conflict.write_bytes(bad)
        # A same-size conflict must be detected even when the timestamp agrees.
        st = (source/conflict.name).stat()
        os.utime(conflict,ns=(st.st_atime_ns,st.st_mtime_ns))
        list_file(selected,fixtures)
        run('copy',common,'immutable_conflict',expected_success=False)
        if conflict.read_bytes()!=bad:
            raise AssertionError('Immutable transfer changed the conflicting destination')
        conflict.rename(archive/conflict.name)
        run('copy',common,'resume_after_fixture_conflict_archived')
        if (raw.stat().st_ino,raw.stat().st_mtime_ns)!=(first_stat.st_ino,first_stat.st_mtime_ns):
            raise AssertionError('Verified prior transfer was copied again')
        run('check',[],'rclone_selected_files_check')
        frozen = snapshot(source,'source')
        frozen['files'] = [row for row in frozen['files'] if row['path'] in fixtures]
        joined = reconcile(frozen,snapshot(destination,'destination'))
        if joined['counts']!={'verified_equal':3,'destination_only':1} or (destination/'not-selected.jpg').exists():
            raise AssertionError('Transfer did not preserve exact selected scope')
        for name,data in fixtures.items():
            verified_copy(destination/name,recovery,name,sha256(data).hexdigest())
        restored = reconcile(frozen,snapshot(recovery,'recovery'))
        if restored['counts']!={'verified_equal':3}:
            raise AssertionError('Independent restore did not match the source')
    return {'status':'completed','rclone':version,'scope':'isolated local directories and generated bytes',
            'events':events,'sha256_reconciliation':joined['counts'],'sha256_recovery':restored['counts'],
            'previous_copy_reused':True,'execution_allowed':False}
